import vision.gears.webgpumath.InstanceElement
import vision.gears.webgpumath.InstanceGroup
import vision.gears.webgpumath.Vec3
import vision.gears.webgpumath.Vec4

// An element of the "lights" array of the shaders.
class Light(group : InstanceGroup) : InstanceElement(group) {

  val position by Vec4(0.0f, 1.0f, 0.0f, 0.0f)
  val powerDensity by Vec3(0.0f, 0.0f, 0.0f)

}
