import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLDivElement
import org.w3c.dom.HTMLCanvasElement
import org.w3c.dom.events.*
import vision.gears.webgpumath.*
import kotlin.js.json

class App(val canvas : HTMLCanvasElement, val overlay : HTMLDivElement, val device : GPUDevice) {

  val context = canvas.getContext("webgpu").unsafeCast<GPUCanvasContext?>() ?: throw Error("Browser does not support WebGPU")
  val canvasFormat = gpu!!.getPreferredCanvasFormat()
  init {
    context.configure(json(
      "device" to device,
      "format" to canvasFormat,
      "alphaMode" to "opaque"))
    // WebGPU reports errors asynchronously
    device.onuncapturederror = { event ->
      console.error(event.error.message)
      overlay.innerHTML = """<font color="red">WebGPU error, see console</font>"""
    }
    // shared shader declarations; uniform providers take their layout from these
    Prelude.load("prelude.wgsl")
  }
  val scene = Scene(device, canvasFormat)
  init {
    resize()
  }

  fun resize() {
    canvas.width = maxOf(canvas.clientWidth, 1)
    canvas.height = maxOf(canvas.clientHeight, 1)
    scene.resize(canvas)
  }

  val keysPressed = HashSet<String>()

  @Suppress("UNUSED_PARAMETER")
  fun registerEventHandlers() {
    document.onkeydown =  {
      event : KeyboardEvent ->
      keysPressed.add( keyNames[event.keyCode] )
    }

    document.onkeyup = {
      event : KeyboardEvent ->
      keysPressed.remove( keyNames[event.keyCode] )
    }

    canvas.onmousedown = {
      event : MouseEvent ->
      scene.camera.mouseDown()
      undefined
    }

    canvas.onmousemove = {
      event : MouseEvent ->
      scene.camera.mouseMove(event)
      event.stopPropagation()
    }

    canvas.onmouseup = {
      event : Event ->
      scene.camera.mouseUp()
      event // This line is a placeholder for event handling code. It has no effect, but avoids the "unused parameter" warning.
    }

    canvas.onmouseout = {
      event : Event ->
      scene.camera.mouseUp()
      event // This line is a placeholder for event handling code. It has no effect, but avoids the "unused parameter" warning.
    }

    window.addEventListener("resize", { resize() })
    window.requestAnimationFrame { update() }
  }

  fun update() {
    // Drawing commands are recorded into a command buffer, then submitted.
    val encoder = device.createCommandEncoder()
    scene.update(encoder, context.getCurrentTexture().createView(), keysPressed)
    device.queue.submit(arrayOf(encoder.finish()))
    window.requestAnimationFrame { update() }
  }
}

fun main() {
  val canvas = document.getElementById("canvas") as HTMLCanvasElement
  val overlay = document.getElementById("overlay") as HTMLDivElement
  overlay.innerHTML = """<font color="red">WebGPU</font>"""

  fun fail(message : String?) {
    console.error(message)
    overlay.innerHTML = """<font color="red">${message}</font>"""
  }

  val gpu = gpu
  if(gpu == null) {
    fail("Browser does not support WebGPU")
    return
  }
  // Getting the device is asynchronous: the app starts when it arrives.
  gpu.requestAdapter().then { adapter ->
    if(adapter == null) {
      fail("No WebGPU adapter found")
    } else {
      adapter.requestDevice().then { device ->
        try{
          val app = App(canvas, overlay, device)
          app.registerEventHandlers()
        } catch(e : Throwable) {
          fail(e.message)
        }
      }
    }
  }
}
