import vision.gears.webgpumath.*
import kotlin.math.exp
import kotlin.math.PI
import kotlin.math.floor

// A game object is an element of the "gameObjects" array of the shaders:
// its uniforms live in its slot of the group's buffer.
open class GameObject(
  group : InstanceGroup,
  vararg val meshes : Mesh
   ) : InstanceElement(group) {

  val position = Vec3()
  var roll = 0.0f
  val scale = Vec3(1.0f, 1.0f, 1.0f)

  val modelMatrix by Mat4()
  val modelMatrixInverse by Mat4()

  var parent : GameObject? = null

  // Every mesh is drawn with instance_index set to our slot in the "gameObjects" array.
  fun draw(pass : Pass, vararg uniformProviders : UniformProvider) {
    meshes.forEach { drawInstance(pass, it, *uniformProviders) }
  }

  fun update() {
    modelMatrix.set().
      scale(scale).
      rotate(roll).
      translate(position)
    parent?.let{ parent ->
      // the parent's transformation is applied after ours
      modelMatrix.premul(parent.modelMatrix)
    }
    modelMatrixInverse.set(modelMatrix).invert()
  }

  open inner class Motion {
    open operator fun invoke(
      dt : Float = 0.016666f,
      t : Float = 0.0f,
      keysPressed : Set<String> = emptySet<String>(),
      gameObjects : List<GameObject> = emptyList<GameObject>(),
      spawn : List<GameObject> = emptyList<GameObject>()
      ) : Boolean {
        return true
    }
  }
  var move = Motion()

}
